function bstInsertVisual(): TreeVisual {
  const base: TreeNode[] = [
    { id: "8", value: 8, left: "3", right: "10" },
    { id: "3", value: 3, left: "1", right: "6" },
    { id: "10", value: 10, left: null, right: "14" },
    { id: "1", value: 1 },
    { id: "6", value: 6, left: null, right: null },
    { id: "14", value: 14 },
  ];
  const path = ["8", "3", "6"];
  const steps: TreeStep[] = [{ note: "Insert **5** into the BST. Start at the root.", nodes: base, root: "8", pointers: [{ name: "curr", nodeId: "8" }], vars: { val: 5 } }];
  const cmp = ["5 < 8 → go left.", "5 > 3 → go right.", "5 < 6 → go left, but `6.left` is null."];
  path.forEach((id, k) =>
    steps.push({
      note: cmp[k],
      nodes: base,
      root: "8",
      pointers: [{ name: "curr", nodeId: id }],
      highlights: [
        { ids: path.slice(0, k), color: "info" },
        { ids: [id], color: "warning" },
      ],
      vars: { val: 5, curr: Number(id) },
    }),
  );
  steps.push({
    note: "Attach **5** as the left child of 6. In-order positions shift to make room.",
    nodes: [...base.map((n) => (n.id === "6" ? { ...n, left: "5" } : n)), { id: "5", value: 5 }],
    root: "8",
    pointers: [{ name: "new", nodeId: "5", color: "success" }],
    highlights: [
      { ids: path, color: "info" },
      { ids: ["5"], color: "success" },
    ],
  });
  return { type: "tree", title: "BST insert 5", steps };
}

function inorderVisual(): TreeVisual {
  const nodes: TreeNode[] = [
    { id: "4", value: 4, left: "2", right: "6" },
    { id: "2", value: 2, left: "1", right: "3" },
    { id: "6", value: 6, left: "5", right: "7" },
    { id: "1", value: 1 },
    { id: "3", value: 3 },
    { id: "5", value: 5 },
    { id: "7", value: 7 },
  ];
  const byId = new Map(nodes.map((n) => [n.id, n]));
  const stack: string[] = [];
  const out: number[] = [];
  const steps: TreeStep[] = [];
  let curr: string | null = "4";
  const snap = (note: string) =>
    steps.push({
      note,
      nodes,
      root: "4",
      pointers: [{ name: "curr", nodeId: curr }],
      highlights: [
        { ids: out.map(String), color: "success" },
        { ids: [...stack], color: "info" },
        ...(curr ? [{ ids: [curr], color: "primary" as ColorKey }] : []),
      ],
      panels: [
        { kind: "stack", title: "stack", items: stack.map(Number), highlight: stack.length ? [stack.length - 1] : [] },
        { kind: "output", title: "output", items: [...out], highlight: out.length ? [out.length - 1] : [] },
      ],
    });
  snap("Iterative in-order: push the whole left spine, then pop, visit, and go right.");
  while (curr || stack.length) {
    while (curr) {
      stack.push(curr);
      curr = byId.get(curr)?.left ?? null;
    }
    snap(`Pushed the left spine; \`curr\` fell off to null.`);
    const top = stack.pop()!;
    out.push(Number(top));
    curr = byId.get(top)?.right ?? null;
    snap(`Pop **${top}** and visit it; move to its right child (${curr ?? "null"}).`);
    if (steps.length > 13) break;
  }
  return { type: "tree", title: "In-order traversal with an explicit stack", steps };
}

function fibTreeVisual(): TreeVisual {
  const nodes: TreeNode[] = [];
  const steps: TreeStep[] = [];
  const done = new Set<string>();
  let seq = 0;
  const label = new Map<string, string>();
  const snap = (note: string, current: string) =>
    steps.push({
      note,
      nodes: nodes.map((n) => ({ ...n, value: label.get(n.id) ?? n.value, children: [...(n.children ?? [])] })),
      root: nodes[0]?.id ?? null,
      highlights: [
        { ids: [...done], color: "success" },
        { ids: [current], color: "primary" },
      ],
    });
  const fib = (n: number, parent: TreeNode | null): number => {
    const id = `f${seq++}`;
    const node: TreeNode = { id, value: `fib(${n})`, children: [] };
    nodes.push(node);
    parent?.children?.push(id);
    if (n < 2) {
      label.set(id, `fib(${n})=${n}`);
      done.add(id);
      snap(`\`fib(${n})\` is a base case → returns ${n}.`, id);
      return n;
    }
    snap(`Call \`fib(${n})\` → needs \`fib(${n - 1})\` and \`fib(${n - 2})\`.`, id);
    const v = fib(n - 1, node) + fib(n - 2, node);
    label.set(id, `fib(${n})=${v}`);
    done.add(id);
    snap(`\`fib(${n})\` returns ${v}.`, id);
    return v;
  };
  fib(4, null);
  return { type: "tree", title: "Recursion tree of fib(4)", caption: "Repeated subtrees (fib(2)) are why memoization helps.", steps };
}

