function bfsVisual(): GraphVisual {
  const nodes = [
    { id: "A", x: 10, y: 50 },
    { id: "B", x: 35, y: 15 },
    { id: "C", x: 35, y: 85 },
    { id: "D", x: 65, y: 15 },
    { id: "E", x: 65, y: 85 },
    { id: "F", x: 92, y: 50 },
  ];
  const edges = [
    { from: "A", to: "B" },
    { from: "A", to: "C" },
    { from: "B", to: "D" },
    { from: "C", to: "E" },
    { from: "B", to: "C" },
    { from: "D", to: "F" },
    { from: "E", to: "F" },
  ];
  const adj = new Map<string, string[]>(nodes.map((n) => [n.id, []]));
  for (const e of edges) {
    adj.get(e.from)!.push(e.to);
    adj.get(e.to)!.push(e.from);
  }
  const dist: Record<string, string> = { A: "0" };
  const visited = new Set(["A"]);
  const queue = ["A"];
  const tree: [string, string][] = [];
  const done: string[] = [];
  const steps: GraphStep[] = [
    {
      note: "BFS from **A**: distance 0, enqueue A.",
      nodeHighlights: [{ ids: ["A"], color: "warning" }],
      nodeBadges: { ...dist },
      panels: [{ kind: "queue", title: "queue", items: [...queue] }],
    },
  ];
  while (queue.length) {
    const u = queue.shift()!;
    const found: string[] = [];
    for (const v of adj.get(u)!) {
      if (visited.has(v)) continue;
      visited.add(v);
      dist[v] = String(Number(dist[u]) + 1);
      queue.push(v);
      tree.push([u, v]);
      found.push(v);
    }
    steps.push({
      note: found.length ? `Dequeue **${u}**; discover ${found.join(", ")} at distance ${Number(dist[u]) + 1}.` : `Dequeue **${u}**; all neighbours already seen.`,
      nodeHighlights: [
        { ids: [...done], color: "info" },
        { ids: [...queue], color: "warning" },
        { ids: [u], color: "primary" },
      ],
      edgeHighlights: [{ edges: [...tree], color: "info" }],
      nodeBadges: { ...dist },
      vars: { u, level: Number(dist[u]) },
      panels: [{ kind: "queue", title: "queue", items: [...queue], highlight: found.map((f) => queue.indexOf(f)) }],
    });
    done.push(u);
  }
  steps.push({ note: "Queue empty. Badges are shortest hop counts from A.", nodeHighlights: [{ ids: done, color: "success" }], edgeHighlights: [{ edges: tree, color: "success" }], nodeBadges: { ...dist } });
  return { type: "graph", title: "BFS shortest hops from A", directed: false, nodes, edges, steps };
}

function dijkstraVisual(): GraphVisual {
  const nodes = [
    { id: "S", x: 6, y: 50 },
    { id: "A", x: 38, y: 12 },
    { id: "B", x: 38, y: 88 },
    { id: "C", x: 70, y: 30 },
    { id: "D", x: 94, y: 72 },
  ];
  const edges = [
    { from: "S", to: "A", weight: 4 },
    { from: "S", to: "B", weight: 1 },
    { from: "B", to: "A", weight: 2 },
    { from: "A", to: "C", weight: 1 },
    { from: "B", to: "D", weight: 7 },
    { from: "C", to: "D", weight: 2 },
    { from: "C", to: "B", weight: 5 },
  ];
  const dist: Record<string, number> = { S: 0, A: Infinity, B: Infinity, C: Infinity, D: Infinity };
  const prevEdge: Record<string, [string, string]> = {};
  const settled: string[] = [];
  const badges = () => Object.fromEntries(Object.entries(dist).map(([k, v]) => [k, v === Infinity ? "∞" : String(v)]));
  const heap = () =>
    Object.entries(dist)
      .filter(([k, v]) => !settled.includes(k) && v !== Infinity)
      .sort((a, b) => a[1] - b[1])
      .map(([k, v]) => `${k}:${v}`);
  const steps: GraphStep[] = [{ note: "`dist[S] = 0`, everything else ∞. The min-heap holds (node, dist).", nodeBadges: badges(), nodeHighlights: [{ ids: ["S"], color: "warning" }], panels: [{ kind: "heap", title: "min-heap", items: heap() }] }];
  while (settled.length < nodes.length) {
    const u = Object.entries(dist)
      .filter(([k]) => !settled.includes(k))
      .sort((a, b) => a[1] - b[1])[0];
    if (!u || u[1] === Infinity) break;
    const [id] = u;
    settled.push(id);
    const relaxed: [string, string][] = [];
    for (const e of edges.filter((x) => x.from === id)) {
      if (dist[id] + e.weight < dist[e.to]) {
        dist[e.to] = dist[id] + e.weight;
        prevEdge[e.to] = [id, e.to];
        relaxed.push([id, e.to]);
      }
    }
    steps.push({
      note: relaxed.length
        ? `Pop **${id}** (dist ${dist[id]}). Relax ${relaxed.map(([, t]) => `${t} → ${dist[t]}`).join(", ")}.`
        : `Pop **${id}** (dist ${dist[id]}). No edge improves anything.`,
      nodeBadges: badges(),
      nodeHighlights: [
        { ids: settled.slice(0, -1), color: "success" },
        { ids: relaxed.map(([, t]) => t), color: "warning" },
        { ids: [id], color: "primary" },
      ],
      edgeHighlights: [
        { edges: Object.values(prevEdge), color: "info" },
        { edges: relaxed, color: "warning" },
      ],
      vars: { u: id, "dist[u]": dist[id] },
      panels: [{ kind: "heap", title: "min-heap", items: heap(), highlight: heap().length ? [0] : [] }],
    });
  }
  steps.push({ note: "All nodes settled: blue edges form the shortest-path tree.", nodeBadges: badges(), nodeHighlights: [{ ids: settled, color: "success" }], edgeHighlights: [{ edges: Object.values(prevEdge), color: "success" }] });
  return { type: "graph", title: "Dijkstra from S (directed, weighted)", directed: true, nodes, edges, steps };
}

