const eventLoopVisual: StateVisual = (() => {
  const P = (stack: string[], micro: string[], macro: string[], out: string[], hot?: { stack?: boolean; micro?: boolean; macro?: boolean; out?: boolean }): Panel[] => [
    { kind: "stack", title: "call stack", items: stack, highlight: hot?.stack && stack.length ? [stack.length - 1] : [] },
    { kind: "queue", title: "microtasks", items: micro, highlight: hot?.micro && micro.length ? [micro.length - 1] : [] },
    { kind: "queue", title: "macrotasks", items: macro, highlight: hot?.macro && macro.length ? [macro.length - 1] : [] },
    { kind: "output", title: "console", items: out, highlight: hot?.out && out.length ? [out.length - 1] : [] },
  ];
  return {
    type: "state",
    title: "Event loop: setTimeout vs Promise",
    caption: "console.log('A'); setTimeout(() => log('B')); Promise.resolve().then(() => log('C')); console.log('D');",
    steps: [
      { note: "The script itself runs as the first task.", panels: P(["main()"], [], [], []) },
      { note: "`console.log('A')` runs synchronously.", panels: P(["main()", "log('A')"], [], [], ["A"], { stack: true, out: true }) },
      { note: "`setTimeout` hands the callback to the timer; it lands in the **macrotask** queue.", panels: P(["main()"], [], ["timeout cb"], ["A"], { macro: true }) },
      { note: "`.then` callback goes to the **microtask** queue.", panels: P(["main()"], ["then cb"], ["timeout cb"], ["A"], { micro: true }) },
      { note: "`console.log('D')` — still synchronous.", panels: P(["main()", "log('D')"], ["then cb"], ["timeout cb"], ["A", "D"], { stack: true, out: true }) },
      { note: "Stack empty → drain **all microtasks** first: prints C.", panels: P(["then cb"], [], ["timeout cb"], ["A", "D", "C"], { stack: true, out: true }) },
      { note: "Only then the next macrotask: prints B. Output **A D C B**.", panels: P(["timeout cb"], [], [], ["A", "D", "C", "B"], { stack: true, out: true }) },
    ],
  };
})();

function roundRobinVisual(): TimelineVisual {
  const bursts: Record<string, number> = { P1: 5, P2: 3, P3: 1 };
  const q = 2;
  const ready = ["P1", "P2", "P3"];
  const remaining = { ...bursts };
  let t = 0;
  const segs: TimelineSegment[] = [];
  const steps: TimelineVisual["steps"] = [{ note: `Round robin, quantum = ${q} ms. All three arrive at t = 0.`, segments: [], panels: [{ kind: "queue", title: "ready queue", items: [...ready] }], vars: { t } }];
  while (ready.length) {
    const p = ready.shift()!;
    const run = Math.min(q, remaining[p]);
    segs.push({ label: p, start: t, end: t + run, lane: p });
    t += run;
    remaining[p] -= run;
    const finished = remaining[p] === 0;
    if (!finished) ready.push(p);
    steps.push({
      note: `${p} runs ${t - run}–${t} ms${finished ? " and **finishes**" : `, ${remaining[p]} ms left → back of the queue`}.`,
      segments: segs.map((s) => ({ ...s })),
      panels: [{ kind: "queue", title: "ready queue", items: [...ready], highlight: finished || !ready.length ? [] : [ready.length - 1] }],
      vars: { t, running: p },
    });
  }
  return { type: "timeline", title: "Round robin (q = 2)", unit: "ms", steps };
}

